from abc import ABCMeta
from six import with_metaclass
from taf.cloud.cbam.session import CbamSession


class CBAM(with_metaclass(ABCMeta, object)):
    vnf = None
    catalog = None

    def __init__(self, ip, client_id, client_secret, verify):
        self._session = CbamSession(cbam_ip=ip, verify=verify)
        self._session.authenticate(client_id=client_id, client_secret=client_secret)

    def is_connected(self):
        return self._session.is_session_open()
